-- === Module-local infrastructure (distributed deployment: no cross-schema access) ===
CREATE TABLE frontoffice.idempotency_key (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    user_id uuid,
    operation_name varchar(120) NOT NULL,
    request_hash varchar(64),
    response_status smallint,
    response_body text,
    locked_at timestamptz,
    completed_at timestamptz,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_frontoffice_idempotency_key PRIMARY KEY (id),
    CONSTRAINT uq_frontoffice_idempotency_key_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE frontoffice.idempotency_key IS 'Module-local idempotency store of the frontoffice module: stored outcome of a write carrying an Idempotency-Key; replays return the stored response. Rows expire after 24h (cleanup job).';
COMMENT ON COLUMN frontoffice.idempotency_key.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN frontoffice.idempotency_key.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
