COMMENT ON COLUMN frontoffice.idempotency_key.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN frontoffice.idempotency_key.updated_at IS 'Last modification time (set by the application on every update).';
